module F3_1_REQ_1Domain refines Domain {
  type Model = (string, set<string>, set<string>)

  datatype Action = Search(query: string)

  ghost predicate Inv(m: Model) {
    var (q, t, s) := m;
    q == "" || q != ""
  }

  function Init(): Model {
    ("", {}, {})
  }

  function Apply(m: Model, a: Action): Model {
    match a
    case Search(q) => 
      var (old_q, torrents, streams) := m;
      (q, torrents, streams)
  }

  function Normalize(m: Model): Model {
    m
  }

  lemma InitSatisfiesInv()
    ensures Inv(Init())
  {
  }

  lemma StepPreservesInv(m: Model, a: Action)
    ensures Inv(Normalize(Apply(m, a)))
  {
  }

  lemma SearchResultAccurate(m: Model, a: Action)
    ensures match a
      case Search(q) =>
        var (query, torrents, streams) := Apply(m, a);
        query == q
      case _ => true
    ensures true
  {
  }
}

